package com.cdac.cssip.meeting.entity;import jakarta.persistence.*;import lombok.*;@Entity @Table(name="meeting_attendees",uniqueConstraints=@UniqueConstraint(columnNames={"meeting_id","student_id"}))@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class MeetingAttendee{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="meeting_id",nullable=false)private Long meetingId;@Column(name="student_id",nullable=false)private Long studentId;}
